package com.cowave.search.outbound_adapter.proxy.brand

import com.cowave.search.client.proxy_api.ProxyApiClient
import com.cowave.search.domain.proxy.brand.BrandProjection
import com.cowave.search.domain.proxy.brand.BrandProxyReader
import org.springframework.stereotype.Component

@Component
class BrandProxyReaderImpl(
    private val client: ProxyApiClient,
) : BrandProxyReader {
    override fun getAllByIds(brandIds: List<Long>): List<BrandProjection> {
        val query =
            """
            query GetBrands(${'$'}ids: [Long!]!) {
                brands(input: { ids: ${'$'}ids }) {
                    items {
                        id
                        name
                    }
                }
            }
            """.trimIndent()

        return client.query(
            query = query,
            variables = mapOf("ids" to brandIds),
            retrievePath = "brands.items",
            BrandProjection::class.java,
        )
    }
}
```

This is almost identical to the existing `BrandRepositoryImpl.kt` but returns `BrandProjection` instead of `Brand`. The GraphQL query is the same.

