package com.cowave.search.outbound_adapter.proxy.brand

import com.cowave.search.domain.proxy.brand.BrandCacheRepository
import com.cowave.search.domain.proxy.brand.BrandProjection
import com.cowave.search.repository.cache.BrandValkeyRepository
import com.cowave.search.repository.cache.entity.BrandValkeyEntity
import com.cowave.shared.cache.GlobalCache
import org.springframework.stereotype.Component

@Component
class BrandCacheRepositoryImpl(
    private val brandValkeyRepository: BrandValkeyRepository,
) : BrandCacheRepository,
    GlobalCache<Long, BrandProjection> {

    override fun getAllByIds(brandIds: List<Long>): List<BrandProjection> =
        brandValkeyRepository.getAllByIds(brandIds)
            .mapNotNull { it?.toProjection() }

    override fun putAll(brands: List<BrandProjection>) {
        brandValkeyRepository.setAll(brands.map { it.toEntity() })
    }

    private fun BrandValkeyEntity.toProjection(): BrandProjection =
        BrandProjection(
            id = id,
            name = name,
        )

    private fun BrandProjection.toEntity(): BrandValkeyEntity =
        BrandValkeyEntity(
            id = id,
            name = name,
        )

    override fun getAll(ids: Collection<Long>): Map<Long, BrandProjection?> {
        val values = brandValkeyRepository.getAllByIds(ids.toList())
        return ids.zip(values).associate {
            it.first to it.second?.toProjection()
        }
    }

    override fun putAll(values: Map<Long, BrandProjection>) {
        brandValkeyRepository.setAll(values.map { (_, v) -> v.toEntity() })
    }
}
```

This follows the `MallRepositoryImpl` pattern exactly: implements both the domain interface (`BrandCacheRepository`) and `GlobalCache<Long, BrandProjection>`.

