class CachedProxyApplicationService(
    private val brandApplicationService: BrandApplicationService,
    private val manufacturerApplicationService: ManufacturerApplicationService,
    private val categoryApplicationService: CategoryApplicationService,
    private val mallApplicationService: MallApplicationService,
) {
    fun fetchDependencies(dependencyId: DependencyId): Dependency =
        runBlocking(Dispatchers.IO) {
            val categoriesDeferred = async {
                if (dependencyId.categoryIds.isEmpty()) emptyMap()
                else categoryApplicationService.getCachedAllByIds(dependencyId.categoryIds)
                    .mapNotNull { (k, v) -> v?.let { k to it.toCategory() } }
                    .toMap()
            }
            val brandsDeferred = async {
                if (dependencyId.brandIds.isEmpty()) emptyMap()
                else brandApplicationService.getCachedAllByIds(dependencyId.brandIds)
                    .mapNotNull { (k, v) -> v?.let { k to it.toBrand() } }
                    .toMap()
            }
            val manufacturersDeferred = async {
                if (dependencyId.manufacturerIds.isEmpty()) emptyMap()
                else manufacturerApplicationService.getCachedAllByIds(dependencyId.manufacturerIds)
                    .mapNotNull { (k, v) -> v?.let { k to it.toManufacturer() } }
                    .toMap()
            }
            val mallsDeferred = async {
                if (dependencyId.mallIds.isEmpty()) emptyMap()
                else mallApplicationService.getCachedAllByIds(dependencyId.mallIds)
                    .mapNotNull { (k, v) -> v?.let { k to Mall(it.mallId, it.mallCode, it.mallIdDanawa, it.mallIdEnuri, it.mallUseYnDanawa, it.mallUseYnEnuri) } }
                    .toMap()
            }

            Dependency(
                categories = categoriesDeferred.await(),
                brands = brandsDeferred.await(),
                manufacturers = manufacturersDeferred.await(),
                malls = mallsDeferred.await(),
            )
        }
}
